  // ===== REAL LOCATION - GPS + MAP =====
  function getRealLocation(sendLive = false) {
    if (!navigator.geolocation) { alert("Is device me GPS nahi hai!"); return; }
    setLocLoading(true);
    navigator.geolocation.getCurrentPosition((pos) => {
      const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy, time: new Date().toLocaleTimeString() };
      setMyLocation(loc); setLocLoading(false); setShowAttach(false);
      pushMsg({ type: "location", lat: loc.lat, lng: loc.lng, accuracy: loc.accuracy, live: sendLive, time: "Now", mapUrl: "https://www.google.com/maps?q=" + loc.lat + "," + loc.lng, embedUrl: "https://www.openstreetmap.org/export/embed.html?bbox=" + (loc.lng - 0.01) + "," + (loc.lat - 0.01) + "," + (loc.lng + 0.01) + "," + (loc.lat + 0.01) + "&layer=mapnik&marker=" + loc.lat + "," + loc.lng });
      if (sendLive) startLiveLocation();
    }, (err) => { setLocLoading(false); alert("Location permission dein! - " + err.message); }, { enableHighAccuracy: true, timeout: 10000 });
  }
  function startLiveLocation() {
    setLiveLoc(true);
    if (liveLocTimer.current) clearInterval(liveLocTimer.current);
    liveLocTimer.current = setInterval(() => {
      navigator.geolocation.getCurrentPosition((pos) => {
        const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
        setMyLocation(loc);
        pushMsg({ type: "location", lat: loc.lat, lng: loc.lng, live: true, time: "Now", mapUrl: "https://www.google.com/maps?q=" + loc.lat + "," + loc.lng, embedUrl: "https://www.openstreetmap.org/export/embed.html?bbox=" + (loc.lng - 0.01) + "," + (loc.lat - 0.01) + "," + (loc.lng + 0.01) + "," + (loc.lat + 0.01) + "&layer=mapnik&marker=" + loc.lat + "," + loc.lng });
      });
    }, 30000);
    setTimeout(() => { stopLiveLocation(); }, 15 * 60 * 1000);
  }
  function stopLiveLocation() { setLiveLoc(false); if (liveLocTimer.current) clearInterval(liveLocTimer.current); }
  // ===== REAL AUDIO FILE - Gana / Music =====
  function onAudioFile(e: any) {
    const f = e.target.files[0]; if (!f) return;
    const reader = new FileReader();
    reader.onloadend = () => { pushMsg({ type: "audiofile", url: reader.result, name: f.name, size: (f.size / 1024 / 1024).toFixed(2) + " MB", time: "Now" }); };
    reader.readAsDataURL(f); setShowAttach(false); alert("Audio bheja ja raha hai: " + f.name);
  }
