  function changeYT() {
    const m = ytUrl.match(/(?:v=|youtu\.be\/|shorts\/)([A-Za-z0-9_-]{11})/);
    if (m) { setYtId(m[1]); setYtTime(0); setYtPlaying(true); }
    else if (ytUrl.includes("youtube")) { alert("Sahi YouTube Link dein!"); }
    else { setYtId(ytUrl); setYtTime(0); setYtPlaying(true); }
  }
  function toggleYTPlay() { setYtPlaying(!ytPlaying); }
