  async function openLiveCamera() { setShowCameraChoice(false); setShowAttach(false); setShowLiveCamera(true); setCapturedPhoto(""); setCameraMode("photo"); try { const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" }, audio: true }); liveStreamRef.current = stream; setTimeout(() => { if (liveVideoRef.current) liveVideoRef.current.srcObject = stream; }, 200); } catch (e) { alert("Camera permission dein!"); setShowLiveCamera(false); } }
  function closeLiveCamera() { if (liveStreamRef.current) { liveStreamRef.current.getTracks().forEach((t: any) => t.stop()); liveStreamRef.current = null; } if (videoRecRef.current && isVideoRec) { try { videoRecRef.current.stop(); } catch (e) { } } setShowLiveCamera(false); setCapturedPhoto(""); setIsVideoRec(false); }
  function capturePhoto() { if (!liveVideoRef.current) return; const video = liveVideoRef.current; const canvas = liveCanvasRef.current; if (!canvas) return; canvas.width = video.videoWidth; canvas.height = video.videoHeight; const ctx = canvas.getContext("2d"); ctx.drawImage(video, 0, 0); const data = canvas.toDataURL("image/jpeg", 0.9); setCapturedPhoto(data); }
  function sendCapturedPhoto() { if (!capturedPhoto) return; pushMsg({ type: "photo", url: capturedPhoto, time: "Now" }); closeLiveCamera(); }
  function startVideoRec() { if (!liveStreamRef.current) return; videoChunks.current = []; const rec = new MediaRecorder(liveStreamRef.current); videoRecRef.current = rec; rec.ondataavailable = (e: any) => { if (e.data.size > 0) videoChunks.current.push(e.data); }; rec.onstop = () => { const blob = new Blob(videoChunks.current, { type: "video/webm" }); const reader = new FileReader(); reader.onloadend = () => { pushMsg({ type: "video", url: reader.result, time: "Now" }); }; reader.readAsDataURL(blob); closeLiveCamera(); }; rec.start(); setIsVideoRec(true); }
  function stopVideoRec() { if (videoRecRef.current && isVideoRec) { try { videoRecRef.current.stop(); } catch (e) { } setIsVideoRec(false); } }
  function onGalleryPick(e: any) { const files = Array.from(e.target.files || []); if (!files.length) return; const items = (files as any[]).map((f: any) => ({ type: f.type.startsWith("video") ? "video" : "photo", url: URL.createObjectURL(f), name: f.name, time: "Now" })); if (items.length === 1) pushMsg(items[0]); else pushMsg({ type: "collage", items, time: "Now" }); setShowCameraChoice(false); setShowAttach(false); }
